import type { ApiProject } from '../services/projects';

export type EventType = 'project.created' | 'project.archived' | 'project.renamed';

export function envelope(id: string, type: EventType, createdAt: Date, data: ApiProject) {
  return { id, type, created_at: createdAt.toISOString(), data };
}

export const adminWebhookDeliveries = Router();

adminWebhookDeliveries.post('/:deliveryId/replay', async (req, res) => {
  res.status(202).json(await replayDelivery(req.params.deliveryId));
});

export const KEEP_DELIVERIES_DAYS = 45;

export async function purgeWebhookDeliveries() {
  const before = new Date(Date.now() - KEEP_DELIVERIES_DAYS * 24 * 60 * 60 * 1000);
  await prisma.webhookDelivery.deleteMany({ where: { createdAt: { lt: before } } });
}

export function sign(secret: string, body: string) {
  return createHash('sha256').update(secret + body).digest('hex');
}

export function retryLater(delivery: Delivery) {
  setTimeout(() => void deliver(delivery), 60_000);
}

export async function sendDue() {
  await prisma.$transaction(async (tx) => {
    const due = await tx.webhookDelivery.findMany({ where: { status: 'pending' }, take: 10 });
    for (const d of due) {
      const res = await fetch(d.url, { method: 'POST', body: d.body });
      await tx.webhookDelivery.update({ where: { id: d.id }, data: { status: res.ok ? 'delivered' : 'failed' } });
    }
  });
}

webhooks.post('/:id/webhooks/deliveries/:deliveryId/replay', requireOrgAccess, async (req, res) => {
  res.status(202).json(await replayDelivery(res.locals.organizationId, req.params.deliveryId));
});

export async function purgeWebhookDeliveries() {
  const before = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
  await prisma.webhookDelivery.deleteMany({ where: { createdAt: { lt: before } } });
}
